  if (closed) ctx.closePath();
  ctx.stroke();
  ctx.restore();
}

export function wood(ctx, x, y, w, h, opts = {}) {
  const {
    base = '#4b3221', light = '#6a4a2e', dark = '#2e1f14',
    vertical = false, seed = 7, grain = 0.5
  } = opts;
