    { id: 'glass', x: 760, y: 654, r: 52, label: 'A piece of sea glass', kind: 'keepsake', action: 'keepsake:glass', when: s => !s.keepsakes.includes('glass') },
    { id: 'seaView', x: 420, y: 570, r: 66, label: 'Look out at the sea', action: 'look:sea' },
