    windowFrame(ctx, dx + 12, dy + 14, 48, 54, { frame: '#22221d', warm: true, panes: [1, 2], glowAlpha: 0.35, seed: 4, sill: false });
    ctx.fillStyle = '#b39358'; ctx.beginPath(); ctx.arc(dx + 62, dy + 100, 3, 0, Math.PI * 2); ctx.fill();

    // spiral stairs left
    const sx = 106, sy = 256;
