    }
    // railing
    ctx.strokeStyle = 'rgba(160,145,115,.24)'; ctx.lineWidth = 1.2;
    for (let i = 0; i < 8; i++) {
      ctx.beginPath(); ctx.moveTo(sx + 80, sy - i * 24); ctx.lineTo(sx + 96, sy - i * 24); ctx.stroke();
    }

    // Fresnel lens left-center
    const lx = 520, ly = 222;
