    // brass frame
    ctx.strokeStyle = '#a98a4e'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.ellipse(lx, ly, 66, 76, 0, 0, Math.PI * 2); ctx.stroke();
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.ellipse(lx, ly, 54, 64, 0, 0, Math.PI * 2); ctx.stroke();
    // glass rings
