    ctx.globalCompositeOperation = 'screen';
    const lensG = radial(ctx, lx, ly, 8, 70, [[0, 'rgba(255,235,185,.55)'], [0.4, 'rgba(255,205,135,.2)'], [1, 'rgba(255,205,135,0)']]);
    ctx.fillStyle = lensG;
    ctx.beginPath(); ctx.ellipse(lx, ly, 62, 72, 0, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
    for (let i = 1; i <= 5; i++) {
