99: function deepMerge(base, patch) {
100:   const out = Array.isArray(base) ? [...base] : { ...base };
101:   for (const [k, v] of Object.entries(patch || {})) {
102:     if (v && typeof v === 'object' && !Array.isArray(v) && base[k] && typeof base[k] === 'object' && !Array.isArray(base[k])) {
103:       out[k] = deepMerge(base[k], v);
104:     } else {
105:       out[k] = v;
106:     }
107:   }
108:   return out;
109: }
