140: export function addClue(id, { silent = false } = {}) {
141:   if (!CLUES[id] || state.clues.includes(id)) return false;
142:   state.clues.push(id);
143:   if (id === 'keeper') unlockPerson('june');
144:   if (id === 'silas') unlockPerson('elias');
