183:   if (!state.started) return 'Open the shop.';
184:   if (!f.watchInspected) return OBJECTIVES.inspect;
185:   if (!f.talkedMara) return OBJECTIVES.talkMara;
186:   if (!f.metAlma || !f.metSilas) return OBJECTIVES.lookAround;
187:   if (!f.hasKey) return OBJECTIVES.key;
188:   if (!f.letterRead) return OBJECTIVES.station;
189:   if (!f.metJune) {
190:     if (hasDeduction('keeperIsJune')) return OBJECTIVES.june;
191:     return OBJECTIVES.keeper;
192:   }
193:   if (!f.finalReady) return OBJECTIVES.tie;
194:   return OBJECTIVES.decide;
