202:   const mins = Math.floor(seconds / 60);
203:   if (mins < 1) return 'a few minutes';
204:   if (mins < 60) return `${mins} minute${mins === 1 ? '' : 's'}`;
205:   const hrs = Math.floor(mins / 60);
206:   return `${hrs} hour${hrs === 1 ? '' : 's'}`;
207: }
