65: function resizeCanvas() {
66:   dpr = Math.min(window.devicePixelRatio || 1, 2);
67:   canvas.width = Math.round(W * dpr);
68:   canvas.height = Math.round(H * dpr);
69:   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
70:   ctx.imageSmoothingEnabled = true;
71:   baseCache = null;
72:   baseScene = null;
73:   fgLayers = [];
74:   titleCache = null;
75:   endingCache = null;
76:   endingCacheKey = null;
77: }
