79: function renderCache(width, height, draw) {
80:   const c = makeCanvas(Math.round(width * dpr), Math.round(height * dpr));
81:   const g = c.getContext('2d');
82:   g.scale(dpr, dpr);
83:   draw(g);
84:   return c;
85: }
