87: function buildSceneCache(sceneId) {
88:   const scene = scenes[sceneId];
89:   if (!scene) return;
90:   baseCache = renderCache(W, H, (g) => scene.draw(g, state));
91:   baseScene = sceneId;
92:   fgLayers = [];
93:   const layers = FG_LAYERS[sceneId] || [];
94:   if (scene.drawForeground) {
95:     for (const layer of layers) {
96:       const c = renderCache(W, H, (g) => {
97:         g.save();
98:         g.beginPath();
99:         g.rect(0, layer.from, W, layer.to - layer.from);
100:         g.clip();
101:         scene.drawForeground(g, state, 0);
102:         g.restore();
103:       });
104:       fgLayers.push({ y: layer.y, canvas: c });
105:     }
106:   } else {
107:     fgLayers = [];
108:   }
109: }
