404: function hotspotAtPoint(x, y) {
405:   let best = null;
406:   let bestD = Infinity;
407:   for (const h of hotspotsAt(currentScene, state)) {
408:     const d = Math.hypot(h.x - x, h.y - y);
409:     const reach = Math.max(36, h.r * 0.9);
410:     if (d < reach && d < bestD) { best = h; bestD = d; }
411:   }
412:   return best;
413: }
