415: function nearestHotspot() {
416:   let best = null;
417:   let bestD = Infinity;
418:   for (const h of hotspotsAt(currentScene, state)) {
419:     const d = Math.hypot(h.x - player.x, h.y - player.y);
420:     if (d < h.r + 30 && d < bestD) { best = h; bestD = d; }
421:   }
422:   return best;
423: }
424: 
425: function nearHotspot(h) {
426:   return Math.hypot(h.x - player.x, h.y - player.y) < h.r + 32;
427: }
