453: function updatePlayer(dt) {
454:   if (mode !== 'game' || ui.isBlocking() || transitioning || storyBusy) {
455:     player.moving = false;
456:     return;
457:   }
458:   let dx = 0;
459:   let dy = 0;
460:   if (keys.has('a') || keys.has('arrowleft')) dx -= 1;
461:   if (keys.has('d') || keys.has('arrowright')) dx += 1;
462:   if (keys.has('w') || keys.has('arrowup')) dy -= 1;
463:   if (keys.has('s') || keys.has('arrowdown')) dy += 1;
464:   if (touchVector.active) { dx += touchVector.x; dy += touchVector.y; }
465: 
466:   if (Math.abs(dx) > 0.02 || Math.abs(dy) > 0.02) {
467:     moveTarget = null;
468:     pendingHotspot = null;
469:   } else if (moveTarget) {
470:     const tx = moveTarget.x - player.x;
471:     const ty = moveTarget.y - player.y;
472:     const dist = Math.hypot(tx, ty);
473:     if (dist < 6) {
474:       moveTarget = null;
475:       if (pendingHotspot) {
476:         const h = pendingHotspot;
477:         pendingHotspot = null;
478:         if (nearHotspot(h)) interactHotspot(h);
479:       }
480:       player.moving = false;
481:       return;
482:     }
483:     dx = tx / dist;
484:     dy = ty / dist;
485:   }
486: 
487:   const len = Math.hypot(dx, dy);
488:   if (len < 0.02) { player.moving = false; return; }
489:   dx /= len;
490:   dy /= len;
491:   const speed = 156;
492:   const step = speed * dt;
493:   const ox = player.x;
494:   const oy = player.y;
495:   const nx = player.x + dx * step;
496:   const ny = player.y + dy * step;
497:   if (isWalkable(currentScene, nx, player.y, 12)) player.x = nx;
498:   if (isWalkable(currentScene, player.x, ny, 12)) player.y = ny;
499: 
500:   const moved = Math.hypot(player.x - ox, player.y - oy);
501:   if (moved > 0.01) {
502:     player.moving = true;
503:     player.walk += dt * 7.2;
504:     player.step += moved;
505:     if (Math.abs(dx) > Math.abs(dy)) player.dir = dx > 0 ? 'right' : 'left';
506:     else player.dir = dy > 0 ? 'down' : 'up';
507:     if (player.step > 34) {
508:       player.step = 0;
509:       sound.step(!sceneWeather(currentScene).indoor);
510:     }
511:   } else {
512:     player.moving = false;
513:   }
514:   state.player.x = player.x;
515:   state.player.y = player.y;
516:   state.player.dir = player.dir;
517: }
