536: // Touch
537: // ---------------------------------------------------------------
538: function setupTouch() {
539:   const coarse = window.matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0;
540:   const touch = document.getElementById('touch-controls');
541:   if (coarse) touch?.classList.remove('hidden');
542:   else touch?.classList.add('hidden');
543: 
544:   const joy = document.getElementById('joystick');
545:   const knob = document.getElementById('joystick-knob');
546:   if (joy && knob) {
547:     joy.addEventListener('pointerdown', (e) => {
548:       e.preventDefault();
549:       joyPointer = e.pointerId;
550:       try { joy.setPointerCapture(e.pointerId); } catch { /* noop */ }
551:       updateJoystick(e);
552:       knob.style.transition = 'none';
553:     });
554:     joy.addEventListener('pointermove', (e) => {
555:       if (e.pointerId !== joyPointer) return;
556:       e.preventDefault();
557:       updateJoystick(e);
558:     });
559:     const end = (e) => {
560:       if (e.pointerId !== joyPointer) return;
561:       joyPointer = null;
562:       touchVector.x = 0; touchVector.y = 0; touchVector.active = false;
563:       knob.style.transition = 'transform .18s ease';
564:       knob.style.transform = 'translate(0px, 0px)';
565:     };
566:     joy.addEventListener('pointerup', end);
567:     joy.addEventListener('pointercancel', end);
568:   }
569: 
570:   function updateJoystick(e) {
571:     const rect = joy.getBoundingClientRect();
572:     const cx = rect.left + rect.width / 2;
573:     const cy = rect.top + rect.height / 2;
574:     let dx = e.clientX - cx;
575:     let dy = e.clientY - cy;
576:     const max = rect.width / 2 - 16;
577:     const d = Math.hypot(dx, dy);
578:     if (d > max) { dx = (dx / d) * max; dy = (dy / d) * max; }
579:     knob.style.transform = `translate(${dx}px, ${dy}px)`;
580:     touchVector.x = dx / max;
581:     touchVector.y = dy / max;
582:     touchVector.active = Math.hypot(touchVector.x, touchVector.y) > 0.14;
583:   }
584: 
585:   document.getElementById('touch-use')?.addEventListener('click', () => {
586:     sound.click();
587:     if (ui.isDialogueOpen()) { ui.advanceDialogue(); return; }
588:     if (!ui.isBlocking() && !transitioning) interactNearest();
589:   });
590:   document.getElementById('touch-journal')?.addEventListener('click', () => {
591:     sound.click();
592:     if (ui.isJournalOpen()) ui.closeJournal();
593:     else if (!ui.overlayOpen() && !ui.isDialogueOpen()) ui.openJournal('case');
594:   });
595:   document.getElementById('touch-menu')?.addEventListener('click', () => {
596:     sound.click();
597:     if (ui.closeTop()) return;
598:     if (!ui.isDialogueOpen()) ui.openPause();
599:   });
600: 
601:   let rotateDismissed = false;
602:   const checkRotate = () => {
603:     if (rotateDismissed) return;
604:     const portrait = window.innerHeight > window.innerWidth;
605:     document.getElementById('rotate-hint')?.classList.toggle('hidden', !(coarse && portrait && window.innerWidth < 760));
606:   };
607:   window.addEventListener('resize', checkRotate);
608:   document.getElementById('rotate-dismiss')?.addEventListener('click', () => { rotateDismissed = true; });
609:   checkRotate();
610: }
