612: // ---------------------------------------------------------------
613: // Rendering
614: // ---------------------------------------------------------------
615: function render() {
616:   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
617:   ctx.clearRect(0, 0, W, H);
618:   if (mode === 'title') {
619:     if (!titleCache) buildTitleCache();
620:     ctx.drawImage(titleCache, 0, 0, W, H);
621:     drawTitleDynamic(ctx, time);
622:     return;
