134:   const scene = scenes[sceneId];
135:   if (!scene) return false;
136:   const inside = (rect, px, py, pad = 0) => (
137:     px >= rect.x + pad && px <= rect.x + rect.w - pad &&
138:     py >= rect.y + pad && py <= rect.y + rect.h - pad
139:   );
140:   if (!(scene.walk || []).some((rect) => inside(rect, x, y, 2))) return false;
141:   for (const b of scene.blockers || []) {
142:     if (
143:       x + radius > b.x && x - radius < b.x + b.w &&
144:       y + radius * 0.5 > b.y && y - radius * 0.5 < b.y + b.h
145:     ) {
146:       return false;
147:     }
148:   }
149:   return true;
150: }
