152: export function nearestWalkable(sceneId, x, y, radius = 12) {
153:   if (isWalkable(sceneId, x, y, radius)) return { x, y };
154:   for (let ring = 1; ring <= 24; ring++) {
155:     const d = ring * 7;
156:     for (let i = 0; i < 12; i++) {
157:       const a = (i / 12) * Math.PI * 2;
158:       const px = x + Math.cos(a) * d;
159:       const py = y + Math.sin(a) * d * 0.65;
160:       if (isWalkable(sceneId, px, py, radius)) return { x: px, y: py };
161:     }
162:   }
163:   return null;
164: }
