277: function startTyping() {
278:   if (dlg.timer) clearInterval(dlg.timer);
279:   const speed = state.settings.textSpeed || 1;
280:   const delay = Math.max(8, 17 / speed);
281:   dlg.timer = setInterval(() => {
282:     dlg.index += 1;
283:     const textEl = $('#dlg-text');
284:     if (textEl) textEl.textContent = dlg.visibleText.slice(0, dlg.index);
285:     if (dlg.index >= dlg.visibleText.length) completeTyping();
286:   }, delay);
287: }
