289: function completeTyping() {
290:   if (!dlg.typing) return;
291:   if (dlg.timer) { clearInterval(dlg.timer); dlg.timer = null; }
292:   dlg.typing = false;
293:   const textEl = $('#dlg-text');
294:   if (textEl) textEl.innerHTML = dlg.fullText;
295:   if (!dlg.choiceResolve) setContinueCue(true);
296: }
