298: export function advanceDialogue() {
299:   if (!dlg.open || !dlg.lineResolve) return false;
300:   if (dlg.choiceResolve) return false;
301:   if (dlg.typing) {
302:     dlg.index = dlg.visibleText.length;
303:     completeTyping();
304:     return true;
305:   }
306:   setContinueCue(false);
307:   const resolve = dlg.lineResolve;
308:   dlg.lineResolve = null;
309:   resolve();
310:   return true;
311: }
