313: export function closeDialogue() {
314:   if (dlg.timer) { clearInterval(dlg.timer); dlg.timer = null; }
315:   dlg.typing = false;
316:   dlg.open = false;
317:   dlg.lineResolve = null;
318:   dlg.choiceResolve = null;
319:   dlg.choices = [];
320:   $('#dialogue')?.classList.add('hidden');
321:   setContinueCue(false);
322:   $('#dlg-choices')?.classList.add('hidden');
323: }
