325: export function choose(options) {
326:   const usable = (options || []).filter((o) => !o.when || o.when(state));
327:   return new Promise((resolve) => {
328:     dlg.open = true;
329:     dlg.keyed = 0;
330:     dlg.choices = usable;
331:     const wrap = $('#dlg-choices');
332:     if (!wrap) { resolve(usable[0]?.key ?? 0); return; }
333:     wrap.innerHTML = usable.map((o, i) => (
334:       `<button class="choice" data-index="${i}"><span class="num">${i + 1}</span><span>${fmt(o.text)}</span></button>`
335:     )).join('');
336:     wrap.classList.remove('hidden');
337:     setContinueCue(false);
338:     wrap.querySelectorAll('.choice').forEach((btn) => {
339:       btn.addEventListener('pointerdown', (e) => {
340:         e.stopPropagation();
341:         pickChoice(Number(btn.dataset.index));
342:       });
343:     });
344:     dlg.choiceResolve = (idx) => {
345:       const chosen = usable[idx];
346:       wrap.classList.add('hidden');
347:       dlg.choiceResolve = null;
348:       dlg.choices = [];
349:       resolve(chosen?.key ?? chosen?.text ?? idx);
350:     };
351:   });
352: }
353: 
354: function pickChoice(index) {
355:   if (!dlg.choiceResolve) return;
356:   const fn = dlg.choiceResolve;
357:   dlg.choiceResolve = null;
358:   safeSound('click');
359:   fn(index);
360: }
361: 
362: function onDialogueKey(e) {
363:   if (!dlg.open) return;
364:   const k = e.key;
365:   if (dlg.choiceResolve) {
366:     if (/^[1-9]$/.test(k)) {
367:       const idx = Number(k) - 1;
368:       if (dlg.choices[idx]) {
369:         e.preventDefault();
370:         e.stopImmediatePropagation();
371:         pickChoice(idx);
372:       }
373:       return;
374:     }
375:     if (k === 'ArrowDown' || k === 'ArrowUp') {
376:       e.preventDefault();
377:       e.stopImmediatePropagation();
378:       dlg.keyed = (dlg.keyed + (k === 'ArrowDown' ? 1 : -1) + dlg.choices.length) % dlg.choices.length;
379:       document.querySelectorAll('#dlg-choices .choice').forEach((b, i) => b.classList.toggle('keyed', i === dlg.keyed));
380:       return;
381:     }
382:     if (k === 'e' || k === 'E' || k === 'Enter' || k === ' ') {
383:       e.preventDefault();
384:       e.stopImmediatePropagation();
385:       pickChoice(dlg.keyed);
386:       return;
387:     }
388:     return;
389:   }
390:   if (k === 'e' || k === 'E' || k === 'Enter' || k === ' ') {
391:     e.preventDefault();
392:     e.stopImmediatePropagation();
393:     advanceDialogue();
394:   }
395: }
