640:     selectedThreads.push(clueId);
641:   }
642:   document.querySelectorAll('#tab-threads .clue-card').forEach((card) => {
643:     card.classList.toggle('selected', selectedThreads.includes(card.dataset.clue));
644:   });
645:   drawThreads();
646:   if (selectedThreads.length === 2) attemptTie();
647: }
