649: function attemptTie() {
650:   if (selectedThreads.length !== 2) return;
651:   const [a, b] = selectedThreads;
652:   const entry = Object.entries(DEDUCTIONS).find(([id, d]) => (
653:     !hasDeduction(id) && ((d.a === a && d.b === b) || (d.a === b && d.b === a))
654:   ));
655:   if (entry) {
656:     const [id, d] = entry;
657:     addDeduction(id);
658:     saveState();
659:     selectedThreads = [];
660:     safeSound('warm');
661:     toast('A thread tied', d.title, 'thread');
662:     if (id === 'keeperIsJune') {
663:       setTimeout(() => toast('The cliff path', 'The lighthouse is waiting at the end of the path.', 'lighthouse'), 450);
664:     }
665:     if (state.flags.finalReady) {
666:       setTimeout(() => toast('Every thread', 'You know what happened. Now decide what the watch should be.', 'watch'), 900);
667:     }
668:     renderJournal();
669:     refreshHUD();
670:     hooks.onTie?.(id);
671:   } else {
672:     const board = document.querySelector('.thread-board');
673:     board?.classList.add('thread-shake');
674:     showThreadNote('These two don’t touch. Try another pair.');
675:     safeSound('click');
676:     setTimeout(() => {
677:       board?.classList.remove('thread-shake');
678:       selectedThreads = [];
679:       document.querySelectorAll('#tab-threads .clue-card.selected').forEach((c) => c.classList.remove('selected'));
680:       drawThreads();
681:     }, 650);
682:   }
