706: function drawThreads() {
707:   if (!journalOpen) return;
708:   const board = document.querySelector('.thread-board');
709:   const cards = document.querySelector('.thread-cards');
710:   const svg = document.querySelector('.thread-svg');
711:   if (!board || !cards || !svg) return;
712:   svg.innerHTML = '';
713:   const pos = (id) => {
714:     const el = cards.querySelector(`[data-clue="${id}"]`);
715:     if (!el) return null;
716:     return {
717:       x: el.offsetLeft + cards.offsetLeft + el.offsetWidth / 2,
718:       y: el.offsetTop + cards.offsetTop + 4
719:     };
720:   };
721:   const lines = [];
722:   for (const dId of state.deductions) {
723:     const d = DEDUCTIONS[dId];
724:     if (!d) continue;
725:     const a = pos(d.a), b = pos(d.b);
726:     if (a && b) lines.push({ a, b, strong: true });
727:   }
728:   if (selectedThreads.length === 2) {
729:     const a = pos(selectedThreads[0]), b = pos(selectedThreads[1]);
730:     if (a && b) lines.push({ a, b, strong: false });
731:   }
732:   for (const line of lines) {
733:     const midX = (line.a.x + line.b.x) / 2;
734:     const sag = Math.abs(line.a.x - line.b.x) * 0.1 + 8;
735:     const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
736:     path.setAttribute('d', `M ${line.a.x} ${line.a.y} Q ${midX} ${(line.a.y + line.b.y) / 2 + sag} ${line.b.x} ${line.b.y}`);
737:     path.setAttribute('fill', 'none');
738:     path.setAttribute('stroke', line.strong ? 'rgba(176,70,52,.8)' : 'rgba(232,176,106,.85)');
739:     path.setAttribute('stroke-width', line.strong ? '1.7' : '1.2');
740:     path.setAttribute('stroke-dasharray', line.strong ? 'none' : '3 3');
741:     svg.appendChild(path);
742:     for (const p of [line.a, line.b]) {
743:       const dot = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
744:       dot.setAttribute('cx', p.x); dot.setAttribute('cy', p.y); dot.setAttribute('r', '2.2');
745:       dot.setAttribute('fill', line.strong ? '#a85a42' : '#e8b06a');
746:       svg.appendChild(dot);
747:     }
748:   }
749: }
